"""Parcel J's acceptance criterion: the HTTP surface, per ADR 0007.

**Written 2026-08-03, before `src/governed_bi/api/` exists.** ADR 0007 is the design; this
file is what makes it checkable. `tools/check_imports.py` has declared an `api` layer since
before v1 was deleted, and nothing has ever been in it.

**Do not edit this file to make it pass.** If a test looks wrong, stop and say so.

Two rules run through all of it, and both are governance rather than plumbing:

1. **A client may not write the run's claims about itself.** `run_id`, `corpus_content_hash`,
   `knobs_resolved` and their siblings are what every quotability gate reads. A
   client-settable provenance field is a forgeable record — the same reason ADR 0006 says no
   tool writes to `licensed`.
2. **A field the engine does not observe must not be invented at the boundary.** The UI wants
   `tier`, `safety_clearance` and `semantic_assurance`; v2 has none of them. Synthesizing one
   in the server would put a reliability claim with nothing behind it on the most prominent
   badge in the interface, which is the defect class the rewrite existed to remove.
"""

from __future__ import annotations

import re
import sys
from pathlib import Path
from typing import Any

import pytest

sys.path.insert(0, str(Path(__file__).resolve().parent.parent))
from contracts import needs  # noqa: E402

#: A specification with no body. Per test, never module-level.
UNWRITTEN = pytest.mark.xfail(strict=True, reason="contract specified, body not yet written")

pytestmark = [needs("J")]

#: `src/governed_bi`, for the structural assertions. Some of these must be structural: a
#: behavioural test that "the server does not synthesize a tier" passes for every input the
#: test happens to try, and says nothing about the next one.
SRC = Path(__file__).resolve().parent.parent.parent / "src" / "governed_bi"


# ── the record is the run's, not the client's ─────────────────────────────────


@UNWRITTEN
def test_a_client_cannot_set_any_provenance_field() -> None:
    """ADR 0007 §2. The most important test here.

    The UI submits one key — `{messages: [{type: "human", content}]}` — and the record
    requires fifteen fields. Something server-side must mint the rest. The failure mode is
    not that it forgets: it is that it **merges** what the client sent.

    `run_id`, `turn_id`, `question_id`, `corpus_content_hash`, `prompt_set_hash`,
    `knobs_resolved` are the run's own claims about itself, and `measure/gates.py` reads them
    to decide whether a run is quotable. A client that can set `corpus_content_hash` can make
    two different corpora report as one, which is a forged comparison rather than a bad one.

    **Fixture shape.** Invoke the graph the way the server does, with a client payload that
    sets every required field to a recognisable sentinel. Assert **no sentinel reaches the
    record** — field by field, from `required_keys()`, not from a hand-written list. Assert
    the turn still succeeds: silently dropping the whole turn would also pass a
    "no sentinel survived" check.
    """
    pytest.fail("not implemented: see docstring")


